const SegmentThreeVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const [cueOne, cueTwo, cueThree, cueFour] = segment.cues;
  const parseReveal = spring({
    frame,
    fps,
    config: { damping: 16, stiffness: 90, mass: 0.9 },
  });
  const terminalReveal = spring({
    frame: Math.max(0, frame - cueTwo.relativeStartFrame),
    fps,
    config: { damping: 18, stiffness: 120, mass: 0.85 },
  });
  const writeBackReveal = spring({
    frame: Math.max(0, frame - cueThree.relativeStartFrame),
    fps,
    config: { damping: 18, stiffness: 112, mass: 0.9 },
  });
  const nextReveal = spring({
    frame: Math.max(0, frame - cueFour.relativeStartFrame),
    fps,
    config: { damping: 18, stiffness: 112, mass: 0.9 },
  });

  const terminalLines = [
    "$ pytest tests/",
    "PASS tests/parser.test.ts",
    "PASS tests/tool-call.test.ts",
    "PASS tests/model-output.test.ts",
    "FAIL tests/runtime.test.ts",
    "E AssertionError: expected runtime.write_back()",
  ];

  const contextLines = [
    "tool_result.stdout: 3 passed, 1 failed",
    "tool_result.stderr: AssertionError at tests/runtime.test.ts",
    "tool_result.command: pytest tests/",
    "runtime.write_back(tool_result)",
  ];

  const nextActionLines = [
    'read_file("tests/runtime.test.ts")',
    'apply_patch("src/runtime.ts")',
    'bash("pytest tests/runtime.test.ts")',
  ];

  const visibleTerminalLines = terminalLines.slice(
    0,
    Math.max(
      1,
      Math.floor(
        interpolate(terminalReveal, [0, 1], [1, terminalLines.length + 0.2], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      )
    )
  );
  const visibleContextLines = contextLines.slice(
    0,
    Math.max(
      1,
      Math.floor(
        interpolate(writeBackReveal, [0, 1], [1, contextLines.length + 0.2], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      )
    )
  );
  const visibleNextActions = nextActionLines.slice(
    0,
    Math.max(
      1,
      Math.floor(
        interpolate(nextReveal, [0, 1], [1, nextActionLines.length + 0.2], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      )
    )
  );

  return (
    <SceneShell segment={segment} eyebrow="Parse, execute, write back, loop again">
      <div style={{ position: "relative", height: "100%" }}>
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "360px 320px 560px 432px",
            gap: 24,
            alignItems: "stretch",
          }}
        >
          <WindowFrame
            title="tool-call.json"
            subtitle="Model output waiting to be parsed"
            style={{
              minHeight: 248,
              opacity: parseReveal,
              boxShadow: `0 24px 100px ${ACCENT}14`,
            }}
          >
            <div
              style={{
                flex: 1,
                borderRadius: 18,
                background: "rgba(0,0,0,0.32)",
                border: "1px solid rgba(255,255,255,0.08)",
                padding: 16,
                display: "flex",
                flexDirection: "column",
                gap: 8,
                fontFamily: THEME.fonts.code,
                fontSize: 15,
                lineHeight: 1.42,
              }}
            >
              <div>{'{'}</div>
              <div>  "type": "tool_use",</div>
              <div>  "name": "bash",</div>
              <div>  "command": "pytest tests/"</div>
              <div>{'}'}</div>
            </div>
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
              {[
                "text from model",
                "awaiting runtime",
              ].map((chip) => (
                <div
                  key={chip}
                  style={{
                    padding: "8px 12px",
                    borderRadius: 999,
                    background: "rgba(255,255,255,0.06)",
                    border: "1px solid rgba(255,255,255,0.08)",
                    fontFamily: THEME.fonts.code,
                    fontSize: 12,
                  }}
                >
                  {chip}
                </div>
              ))}
            </div>
          </WindowFrame>

          <WindowFrame
            title="runtime.ts"
            subtitle="The executor that parses the tool call"
            headerRight={
              <div
                style={{
                  padding: "8px 12px",
                  borderRadius: 999,
                  background: `${ACCENT}1A`,
                  border: `1px solid ${ACCENT}33`,
                  fontFamily: THEME.fonts.code,
                  fontSize: 12,
                }}
              >
                real executor
              </div>
            }
