const FlowArrow: React.FC<{ progress: number; style?: React.CSSProperties }> = ({ progress, style }) => {
  const width = interpolate(progress, [0, 1], [0, 32], { extrapolateRight: "clamp" });
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        alignSelf: "center",
        ...style,
      }}
    >
      <div
        style={{
          width,
          height: 3,
          borderRadius: 999,
          background: `linear-gradient(90deg, ${ACCENT}44, ${ACCENT}CC)`,
          boxShadow: progress > 0.5 ? `0 0 12px ${ACCENT}44` : "none",
          opacity: progress,
        }}
      />
      <div
        style={{
          width: 0,
          height: 0,
          borderTop: "6px solid transparent",
          borderBottom: "6px solid transparent",
          borderLeft: `8px solid ${ACCENT}CC`,
          opacity: progress,
        }}
      />
    </div>
  );
};

const SegmentThreeVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const [cueOne, cueTwo, cueThree, cueFour] = segment.cues;

  const parseReveal = spring({
    frame,
    fps,
    config: { damping: 16, stiffness: 90, mass: 0.9 },
  });
  const terminalReveal = spring({
    frame: Math.max(0, frame - cueTwo.relativeStartFrame),
    fps,
    config: { damping: 18, stiffness: 120, mass: 0.85 },
  });
  const writeBackReveal = spring({
    frame: Math.max(0, frame - cueThree.relativeStartFrame),
    fps,
    config: { damping: 18, stiffness: 112, mass: 0.9 },
  });
  const nextReveal = spring({
    frame: Math.max(0, frame - cueFour.relativeStartFrame),
    fps,
    config: { damping: 18, stiffness: 112, mass: 0.9 },
  });

  const activePhase =
    nextReveal > 0.12 ? 3 : writeBackReveal > 0.12 ? 2 : terminalReveal > 0.12 ? 1 : 0;

  const panelHighlight = (index: number, reveal: number): React.CSSProperties => ({
    opacity: Math.max(0.35, reveal),
    transform: `translateY(${interpolate(reveal, [0, 1], [40, 0])}px)`,
    boxShadow: activePhase === index ? `0 0 40px ${ACCENT}22, 0 20px 60px rgba(0,0,0,0.3)` : "0 18px 60px rgba(0,0,0,0.2)",
    border: activePhase === index ? `1px solid ${ACCENT}44` : `1px solid ${ACCENT}18`,
  });

  const terminalLines = [
    "$ pytest tests/",
    "PASS tests/parser.test.ts",
    "FAIL tests/runtime.test.ts",
    "E AssertionError: expected write_back()",
  ];

  const contextLines = [
    "stdout: 1 passed, 1 failed",
    "stderr: AssertionError",
    "write_back(tool_result)",
  ];

  const visibleTerminalLines = terminalLines.slice(
    0,
    Math.max(1, Math.floor(interpolate(terminalReveal, [0, 1], [1, terminalLines.length + 0.2], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })))
  );
  const visibleContextLines = contextLines.slice(
    0,
    Math.max(1, Math.floor(interpolate(writeBackReveal, [0, 1], [1, contextLines.length + 0.2], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })))
  );

  return (
    <SceneShell segment={segment} eyebrow="Parse, execute, write back, loop again">
      <div style={{ position: "relative", height: "100%" }}>
        <div
          style={{
            display: "flex",
            gap: 12,
            alignItems: "stretch",
          }}
        >
          <WindowFrame
            title="1. Parse"
            style={{
              flex: 1,
              minHeight: 240,
              ...panelHighlight(0, parseReveal),
            }}
          >
            <div
              style={{
                flex: 1,
                borderRadius: 18,
                background: "rgba(0,0,0,0.32)",
                border: "1px solid rgba(255,255,255,0.08)",
                padding: 14,
                display: "flex",
                flexDirection: "column",
                gap: 6,
                fontFamily: THEME.fonts.code,
                fontSize: 14,
                lineHeight: 1.42,
              }}
            >
              <div>{'{'}</div>
              <div>  "name": "bash",</div>
              <div>  "command": "pytest tests/"</div>
              <div>{'}'}</div>
            </div>
            <StepBadge label="parse → real action" active={activePhase === 0} />
          </WindowFrame>

          <FlowArrow progress={terminalReveal} />

          <WindowFrame
            title="2. Execute"
            style={{
              flex: 1.2,
              minHeight: 240,
              ...panelHighlight(1, terminalReveal),
            }}
          >
            <div
              style={{
                flex: 1,
                borderRadius: 18,
                background: "rgba(0,0,0,0.32)",
                border: "1px solid rgba(255,255,255,0.08)",
                padding: 14,
                display: "flex",
                flexDirection: "column",
                gap: 6,
                fontFamily: THEME.fonts.code,
                fontSize: 15,
              }}
            >
              {visibleTerminalLines.map((line, i) => (
                <div key={`t-${i}`} style={{ color: line.includes("FAIL") || line.includes("Assertion") ? "#FF7B72" : THEME.colors.textPrimary }}>
                  {line}
                </div>
              ))}
            </div>
          </WindowFrame>

          <FlowArrow progress={writeBackReveal} />

          <WindowFrame
            title="3. Write Back"
            style={{
              flex: 1,
              minHeight: 240,
              ...panelHighlight(2, writeBackReveal),
            }}
          >
            <div
              style={{
                flex: 1,
                borderRadius: 18,
                background: "rgba(0,0,0,0.24)",
                border: "1px solid rgba(255,255,255,0.08)",
                padding: 14,
                display: "flex",
                flexDirection: "column",
                gap: 8,
                fontFamily: THEME.fonts.code,
                fontSize: 14,
              }}
            >
              {visibleContextLines.map((line, i) => (
                <div
                  key={`c-${i}`}
                  style={{
                    padding: "8px 10px",
                    borderRadius: 14,
                    background: i === visibleContextLines.length - 1 ? `${ACCENT}18` : "rgba(255,255,255,0.04)",
                    border: `1px solid ${i === visibleContextLines.length - 1 ? `${ACCENT}34` : "rgba(255,255,255,0.08)"}`,
                  }}
                >
                  {line}
                </div>
              ))}
            </div>
          </WindowFrame>

          <FlowArrow progress={nextReveal} />

          <WindowFrame
            title="4. Loop"
            style={{
              flex: 1,
              minHeight: 240,
              ...panelHighlight(3, nextReveal),
            }}
          >
            <div
              style={{
                flex: 1,
                display: "flex",
                flexDirection: "column",
                gap: 10,
              }}
            >
              {["read_file(…)", "apply_patch(…)", "bash(…)"].map((action, i) => {
                const actionReveal = interpolate(nextReveal, [0, 1], [0, 1], { extrapolateRight: "clamp" });
                const stagger = Math.min(1, Math.max(0, actionReveal * 3 - i));
                return (
                  <div
                    key={`a-${i}`}
                    style={{
                      padding: "12px 14px",
                      borderRadius: 16,
                      background: i === 2 ? `${ACCENT}18` : "rgba(255,255,255,0.05)",
                      border: `1px solid ${i === 2 ? `${ACCENT}34` : "rgba(255,255,255,0.08)"}`,
                      fontFamily: THEME.fonts.code,
                      fontSize: 15,
                      opacity: stagger,
                      transform: `translateX(${interpolate(stagger, [0, 1], [20, 0])}px)`,
                    }}
                  >
                    {action}
                  </div>
                );
              })}
            </div>
            <div
              style={{
                fontFamily: THEME.fonts.title,
                fontSize: 18,
                fontWeight: 700,
                color: `${ACCENT}DD`,
                textAlign: "center",
                opacity: nextReveal,
              }}
            >
              loop continues →
            </div>
          </WindowFrame>
        </div>

        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 0,
            height: 4,
            borderRadius: 999,
            background: "rgba(255,255,255,0.06)",
            marginTop: 20,
          }}
        >
          <div
            style={{
              height: "100%",
              borderRadius: 999,
              width: `${interpolate(activePhase, [0, 3], [25, 100])}%`,
              background: `linear-gradient(90deg, ${ACCENT}88, ${ACCENT}CC)`,
              boxShadow: `0 0 16px ${ACCENT}44`,
            }}
          />
        </div>
      </div>
    </SceneShell>
  );
};

