export const BilingualSubtitle: React.FC<Props> = ({
  cues,
  accentColor = THEME.seriesAccent["ai-agents"],
}) => {
  const frame = useCurrentFrame();
  const activeCue = cues.find(
    (cue) =>
      frame >= cue.relativeStartFrame && frame < cue.relativeEndFrameExclusive
  );

  if (!activeCue) {
    return null;
  }

  const duration = Math.max(
    1,
    activeCue.relativeEndFrameExclusive - activeCue.relativeStartFrame
  );
  const cueProgress = interpolate(
    frame,
    [activeCue.relativeStartFrame, activeCue.relativeEndFrameExclusive],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const progressWidth = `${Math.max(8, cueProgress * 100)}%`;

  const cnSegments = activeCue.cn.split("|");
  const enSegments = activeCue.en.split("|");
  const segCount = Math.max(cnSegments.length, enSegments.length);
  const activeSegIdx = Math.min(Math.floor(cueProgress * segCount), segCount - 1);
  const displayCn = cnSegments[activeSegIdx] || cnSegments[cnSegments.length - 1];
  const displayEn = enSegments[activeSegIdx] || enSegments[enSegments.length - 1];

