const SegmentTwoVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const [cueOne, cueTwo, cueThree] = segment.cues;
  const cueTwoStart = cueTwo.relativeStartFrame;
  const cueThreeStart = cueThree.relativeStartFrame;

  const cueOneFade = interpolate(frame, [0, 12, cueTwoStart - 8, cueTwoStart], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cueTwoFade = interpolate(frame, [cueTwoStart, cueTwoStart + 12, cueThreeStart - 8, cueThreeStart], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cueThreeFade = interpolate(frame, [cueThreeStart, cueThreeStart + 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const msgReveal = spring({ frame: Math.max(0, frame - 10), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const llmReveal = spring({ frame: Math.max(0, frame - 40), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const toolReveal = spring({ frame: Math.max(0, frame - cueTwoStart), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const outputReveal = spring({ frame: Math.max(0, frame - cueTwoStart - 30), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const termReveal = spring({ frame: Math.max(0, frame - cueThreeStart), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const toolCallText = '{\n  "type": "tool_use",\n  "name": "bash",\n  "command": "pytest tests/"\n}';
  const phaseBLocal = Math.max(0, frame - cueTwoStart - 30);
  const toolTyped = Math.floor(interpolate(phaseBLocal, [0, 80], [0, toolCallText.length], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
  const toolCursor = phaseBLocal > 0 && phaseBLocal < 90 && Math.floor(frame / 10) % 2 === 0;

  const termCursor = frame > cueThreeStart && Math.floor(frame / 16) % 2 === 0;

  return (
    <>
      <GridBackdrop />
      <div style={{ position: "relative", width: "100%", height: "100%", padding: "40px 40px 220px" }}>

        {/* Phase A: User message enters model */}
        <div
          style={{
            position: "absolute",
            left: 40, right: 40, top: 60, bottom: 220,
            display: "grid",
            gridTemplateColumns: "1fr auto 400px",
            gap: 24,
            alignItems: "center",
            opacity: cueOneFade,
            pointerEvents: cueOneFade < 0.1 ? "none" : "auto",
          }}
        >
          <WindowFrame
            title="user-message.txt"
            style={{
              opacity: msgReveal,
              transform: `translateY(${interpolate(msgReveal, [0, 1], [40, 0])}px)`,
              minHeight: 340,
            }}
          >
            <div
              style={{
                flex: 1, borderRadius: 18,
                background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)",
                padding: 32, fontFamily: THEME.fonts.code, fontSize: 26, lineHeight: 1.65,
              }}
            >
              <div style={{ color: "#79C0FF" }}>// 用户发送的消息</div>
              <div style={{ color: THEME.colors.textSecondary }}> </div>
              <div style={{ color: THEME.colors.textPrimary, fontSize: 32, fontWeight: 700 }}>
                "帮我跑一下测试"
              </div>
              <div style={{ color: THEME.colors.textSecondary }}> </div>
              <div style={{ color: THEME.colors.textSecondary }}>// → 这段文字会被拼进 prompt</div>
              <div style={{ color: THEME.colors.textSecondary }}>// → 和系统指令一起送进模型</div>
            </div>
          </WindowFrame>

          <FlowArrow progress={llmReveal} length={60} />

          <LlmBlock
            style={{
              width: "100%", minHeight: 340,
              opacity: llmReveal,
              transform: `scale(${interpolate(llmReveal, [0, 1], [0.85, 1])})`,
            }}
          />
        </div>

        {/* Phase B: Model emits tool call text */}
        <div
          style={{
            position: "absolute",
            left: 40, right: 40, top: 40, bottom: 220,
            display: "grid",
            gridTemplateColumns: "1fr auto 420px auto 1fr",
            gap: 16,
            alignItems: "center",
            opacity: cueTwoFade,
            pointerEvents: cueTwoFade < 0.1 ? "none" : "auto",
          }}
        >
          <WindowFrame
            title="prompt (text)"
            style={{
              opacity: toolReveal,
              transform: `translateX(${interpolate(toolReveal, [0, 1], [-30, 0])}px)`,
              minHeight: 300,
            }}
          >
            <div
              style={{
                flex: 1, borderRadius: 18,
                background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)",
                padding: 28, fontFamily: THEME.fonts.code, fontSize: 22, lineHeight: 1.6,
              }}
            >
              <div style={{ color: "#79C0FF" }}>&lt;system&gt;</div>
              <div style={{ color: THEME.colors.textSecondary }}>  You are a coding agent...</div>
              <div style={{ color: "#79C0FF" }}>&lt;/system&gt;</div>
              <div style={{ color: "#79C0FF" }}>&lt;user&gt;</div>
              <div style={{ color: THEME.colors.textPrimary }}>  帮我跑一下测试</div>
              <div style={{ color: "#79C0FF" }}>&lt;/user&gt;</div>
            </div>
          </WindowFrame>

          <FlowArrow progress={toolReveal} />

          <LlmBlock
            style={{
              width: "100%", minHeight: 380,
              opacity: toolReveal,
              transform: `scale(${interpolate(toolReveal, [0, 1], [0.9, 1])})`,
            }}
          />

          <FlowArrow progress={outputReveal} />

          <WindowFrame
            title="output (text)"
            style={{
              opacity: outputReveal,
              transform: `translateX(${interpolate(outputReveal, [0, 1], [30, 0])}px)`,
              minHeight: 300,
            }}
          >
            <div
              style={{
                flex: 1, borderRadius: 18,
                background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)",
                padding: 28, fontFamily: THEME.fonts.code, fontSize: 22, lineHeight: 1.6,
              }}
            >
              <pre style={{ margin: 0, whiteSpace: "pre-wrap", color: THEME.colors.textPrimary }}>
                {toolCallText.slice(0, toolTyped)}{toolCursor ? "▋" : ""}
              </pre>
            </div>
          </WindowFrame>
        </div>

        {/* Phase C: Terminal is idle */}
        <div
          style={{
            position: "absolute",
            left: 40, right: 40, top: 40, bottom: 220,
            display: "flex",
            flexDirection: "column",
            gap: 32,
            opacity: cueThreeFade,
            pointerEvents: cueThreeFade < 0.1 ? "none" : "auto",
          }}
        >
          {/* Top: repeat the tool call output small + "still just text" label */}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 24 }}>
            <WindowFrame
              title="model output (text)"
              style={{
                opacity: termReveal,
                transform: `translateY(${interpolate(termReveal, [0, 1], [20, 0])}px)`,
              }}
            >
              <div
                style={{
                  flex: 1, borderRadius: 18,
                  background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)",
                  padding: 24, fontFamily: THEME.fonts.code, fontSize: 20, lineHeight: 1.55,
                }}
              >
                <pre style={{ margin: 0, whiteSpace: "pre-wrap", color: THEME.colors.textPrimary }}>
                  {toolCallText}
                </pre>
                <div style={{ marginTop: 16, padding: "10px 18px", borderRadius: 12, background: `${ACCENT}18`, border: `1px solid ${ACCENT}44`, fontFamily: THEME.fonts.code, fontSize: 16, color: ACCENT }}>
                  ↑ 这仍然只是模型生成的文本
                </div>
              </div>
            </WindowFrame>

            <WindowFrame
              title="Terminal"
              style={{
                opacity: termReveal,
                transform: `translateY(${interpolate(termReveal, [0, 1], [20, 0])}px)`,
              }}
              headerRight={
                <div style={{
                  padding: "6px 14px", borderRadius: 999,
                  background: "rgba(248,81,73,0.14)", border: "1px solid rgba(248,81,73,0.38)",
                  fontFamily: THEME.fonts.code, fontSize: 16, color: "#FFB3AD",
                }}>
                  idle — 未启动
                </div>
              }
            >
              <div
                style={{
                  flex: 1, borderRadius: 18,
                  background: "rgba(0,0,0,0.4)", border: "1px solid rgba(255,255,255,0.08)",
                  padding: 24, fontFamily: THEME.fonts.code, fontSize: 22, lineHeight: 1.7,
                }}
              >
                <div style={{ color: THEME.colors.textPrimary }}>$ {termCursor ? "▋" : " "}</div>
                <div style={{ color: THEME.colors.textSecondary }}> </div>
                <div style={{ color: THEME.colors.textSecondary }}>// pytest tests/ 还没有被执行</div>
                <div style={{ color: THEME.colors.textSecondary }}>// 没有 stdout</div>
                <div style={{ color: THEME.colors.textSecondary }}>// 没有 stderr</div>
                <div style={{ color: THEME.colors.textSecondary }}> </div>
                <div style={{ color: "#FF7B72" }}>// 终端完全空闲</div>
              </div>
            </WindowFrame>
          </div>
        </div>

      </div>
    </>
  );
};

