const SegmentTwoVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const [, cueTwo, cueThree] = segment.cues;
  const cueTwoStart = cueTwo.relativeStartFrame;
  const cueThreeStart = cueThree.relativeStartFrame;

  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  const msgReveal = spring({ frame: Math.max(0, frame - 10), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const arrowToLlm = spring({ frame: Math.max(0, frame - 50), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const llmReveal = spring({ frame: Math.max(0, frame - 70), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const morphAB = spring({ frame: Math.max(0, frame - cueTwoStart + 15), fps, config: { damping: 22, stiffness: 60, mass: 1.2 } });
  const outputReveal = spring({ frame: Math.max(0, frame - cueTwoStart - 20), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const morphBC = spring({ frame: Math.max(0, frame - cueThreeStart + 15), fps, config: { damping: 22, stiffness: 60, mass: 1.2 } });
  const termReveal = spring({ frame: Math.max(0, frame - cueThreeStart - 10), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const userMsgText = "帮我跑一下测试";
  const phaseALocal = Math.max(0, frame - 10);
  const userMsgTyped = Math.floor(interpolate(phaseALocal, [15, 55], [0, userMsgText.length], clamp));
  const userMsgCursor = phaseALocal > 10 && phaseALocal < 65 && Math.floor(frame / 10) % 2 === 0;

  const fullResponseText = '好的，我来帮你跑一下测试。\n让我先执行测试命令：\n\n{\n  "type": "tool_use",\n  "name": "bash",\n  "command": "pytest tests/"\n}';
  const phaseBLocal = Math.max(0, frame - cueTwoStart - 20);
  const responseTyped = Math.floor(interpolate(phaseBLocal, [0, 160], [0, fullResponseText.length], clamp));
  const toolCursor = phaseBLocal > 0 && phaseBLocal < 170 && Math.floor(frame / 10) % 2 === 0;

  const termCursor = frame > cueThreeStart && Math.floor(frame / 16) % 2 === 0;
  const idlePulse = interpolate(Math.sin(frame / 18), [-1, 1], [0.6, 1]);

  const LEFT = 40;
  const TOP = 40;
  const CANVAS_W = 1920 - 80;
  const CANVAS_H = 1080 - 40 - 220;
  const GAP = 20;
  const ARROW_W = 60;

  const promptWidth = interpolate(morphAB, [0, 1], [CANVAS_W - ARROW_W - GAP - 400, (CANVAS_W - 380 - 2 * ARROW_W - 4 * GAP) / 2], clamp);
  const promptLeft = LEFT;
  const promptTop = TOP;
  const promptHeight = CANVAS_H;

  const llmLeft = interpolate(morphAB, [0, 1], [CANVAS_W - 400 + LEFT, LEFT + promptWidth + ARROW_W + 2 * GAP], clamp);
  const llmWidth = interpolate(morphAB, [0, 1], [400, 380], clamp);
  const llmOpacity = interpolate(morphBC, [0, 1], [1, 0], clamp);

  const outputLeft = llmLeft + llmWidth + ARROW_W + 2 * GAP;
  const outputWidth = CANVAS_W + LEFT - outputLeft;

  const modelOutLeft = interpolate(morphBC, [0, 1], [outputLeft, LEFT], clamp);
  const modelOutWidth = interpolate(morphBC, [0, 1], [outputWidth, (CANVAS_W - GAP) / 2], clamp);

  const termLeft = LEFT + (CANVAS_W + GAP) / 2;
  const termWidth = (CANVAS_W - GAP) / 2;

  const promptOpacity = interpolate(morphBC, [0, 1], [1, 0], clamp);
  const promptTitle = morphAB < 0.5 ? "user-message.txt" : "prompt (text)";

  return (
    <>
      <GridBackdrop />
      <div style={{ position: "relative", width: "100%", height: "100%" }}>

        {/* Prompt / User-message window — morphs from wide to narrow */}
        <WindowFrame
          title={promptTitle}
          style={{
            position: "absolute",
            left: promptLeft,
            top: promptTop,
            width: promptWidth,
            height: promptHeight,
            opacity: msgReveal * promptOpacity,
            transform: `translateY(${interpolate(msgReveal, [0, 1], [40, 0])}px)`,
          }}
        >
          <div
            style={{
              flex: 1, borderRadius: 18,
              background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)",
              padding: interpolate(morphAB, [0, 1], [32, 24], clamp),
              fontFamily: THEME.fonts.code,
              fontSize: interpolate(morphAB, [0, 1], [26, 20], clamp),
              lineHeight: 1.6, overflow: "hidden",
            }}
          >
            {morphAB < 0.5 ? (
              <>
                <div style={{ color: "#79C0FF" }}>// 用户发送的消息</div>
                <div style={{ color: THEME.colors.textSecondary }}> </div>
                <div style={{ color: THEME.colors.textPrimary, fontSize: 32, fontWeight: 700 }}>
                  "{userMsgText.slice(0, userMsgTyped)}{userMsgCursor ? "▋" : ""}"
                </div>
                <div style={{ color: THEME.colors.textSecondary }}> </div>
                <div style={{ color: THEME.colors.textSecondary }}>// → 这段文字会被拼进 prompt</div>
                <div style={{ color: THEME.colors.textSecondary }}>// → 和系统指令一起送进模型</div>
              </>
            ) : (
              <>
                <div style={{ color: "#79C0FF" }}>&lt;system&gt;</div>
                <div style={{ color: THEME.colors.textSecondary }}>  You are a coding agent...</div>
                <div style={{ color: "#79C0FF" }}>&lt;/system&gt;</div>
                <div style={{ color: "#79C0FF" }}>&lt;user&gt;</div>
                <div style={{ color: THEME.colors.textPrimary }}>  帮我跑一下测试</div>
                <div style={{ color: "#79C0FF" }}>&lt;/user&gt;</div>
              </>
            )}
          </div>
        </WindowFrame>

        {/* Arrow: prompt → LLM */}
        <div style={{
          position: "absolute",
          left: promptLeft + promptWidth + GAP,
          top: TOP + CANVAS_H / 2 - 10,
          opacity: arrowToLlm * llmOpacity,
        }}>
          <FlowArrow progress={arrowToLlm} length={ARROW_W} />
        </div>

        {/* LLM block — slides from right to center, then fades in phase C */}
        <LlmBlock
          style={{
            position: "absolute",
            left: llmLeft,
            top: TOP + (CANVAS_H - 380) / 2,
            width: llmWidth,
            height: 380,
            opacity: llmReveal * llmOpacity,
            transform: `scale(${interpolate(llmReveal, [0, 1], [0.85, 1])})`,
          }}
        />

        {/* Arrow: LLM → output (only in phase B) */}
        <div style={{
          position: "absolute",
          left: llmLeft + llmWidth + GAP,
          top: TOP + CANVAS_H / 2 - 10,
          opacity: outputReveal * llmOpacity,
        }}>
          <FlowArrow progress={outputReveal} length={ARROW_W} />
        </div>

        {/* Output / model-output window — appears in B, morphs to left-half in C */}
        <WindowFrame
          title={morphBC < 0.5 ? "output (text)" : "model output (text)"}
          style={{
            position: "absolute",
            left: modelOutLeft,
            top: TOP,
            width: modelOutWidth,
            height: CANVAS_H,
            opacity: outputReveal,
            transform: `translateX(${interpolate(outputReveal, [0, 1], [30, 0])}px)`,
          }}
        >
          <div
            style={{
              flex: 1, borderRadius: 18,
              background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)",
              padding: 24, fontFamily: THEME.fonts.code,
              fontSize: interpolate(morphBC, [0, 1], [20, 18], clamp),
              lineHeight: 1.55,
            }}
          >
            {(() => {
              const showFull = morphBC > 0.5;
              const text = showFull ? fullResponseText : fullResponseText.slice(0, responseTyped);
              const toolStartIdx = fullResponseText.indexOf("{");
              return (
                <pre style={{ margin: 0, whiteSpace: "pre-wrap" }}>
                  <span style={{ color: THEME.colors.textSecondary }}>{text.slice(0, Math.min(text.length, toolStartIdx))}</span>
                  {text.length > toolStartIdx && (
                    <span style={{ color: ACCENT, fontWeight: 600 }}>{text.slice(toolStartIdx)}</span>
                  )}
                  {!showFull && toolCursor ? "▋" : ""}
                </pre>
              );
            })()}
            {morphBC > 0.3 && (
              <div style={{
                marginTop: 16, padding: "12px 20px", borderRadius: 14,
                background: `${ACCENT}14`, border: `1px solid ${ACCENT}33`,
                fontFamily: THEME.fonts.code, fontSize: 17, color: ACCENT,
                opacity: interpolate(morphBC, [0.3, 0.8], [0, 1], clamp),
              }}>
                ↑ 仍然只是模型生成的文本
              </div>
            )}
          </div>
        </WindowFrame>

        {/* Terminal — slides in from right in phase C */}
        <WindowFrame
          title="Terminal"
          style={{
            position: "absolute",
            left: termLeft,
            top: TOP,
            width: termWidth,
            height: CANVAS_H,
            opacity: termReveal,
            transform: `translateX(${interpolate(termReveal, [0, 1], [40, 0])}px)`,
          }}
          headerRight={
            <div style={{
              padding: "6px 14px", borderRadius: 999,
              background: "rgba(248,81,73,0.14)", border: "1px solid rgba(248,81,73,0.38)",
              fontFamily: THEME.fonts.code, fontSize: 16, color: "#FFB3AD",
              opacity: idlePulse,
            }}>
              idle — 未启动
            </div>
          }
        >
          <div
            style={{
              flex: 1, borderRadius: 18,
              background: "rgba(0,0,0,0.4)", border: "1px solid rgba(255,255,255,0.08)",
              padding: 24, fontFamily: THEME.fonts.code, fontSize: 22, lineHeight: 1.7,
              display: "flex", flexDirection: "column", justifyContent: "center",
            }}
          >
            <div style={{ color: THEME.colors.textPrimary }}>$ {termCursor ? "▋" : " "}</div>
            <div style={{ color: THEME.colors.textSecondary, marginTop: 20 }}> </div>
            <div style={{ color: THEME.colors.textSecondary }}>// pytest tests/ 还没有被执行</div>
            <div style={{ color: THEME.colors.textSecondary }}>// 没有 stdout</div>
            <div style={{ color: THEME.colors.textSecondary }}>// 没有 stderr</div>
            <div style={{ color: THEME.colors.textSecondary }}> </div>
            <div style={{ color: "#FF7B72" }}>// 终端完全空闲</div>
          </div>
        </WindowFrame>

      </div>
    </>
  );
};

