    const fadeIn = interpolate(frame, [cue.relativeStartFrame, cue.relativeStartFrame + 12], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    const fadeOut = next ? interpolate(frame, [next.relativeStartFrame - 8, next.relativeStartFrame], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 1;
    return Math.min(fadeIn, fadeOut);
