const SegmentThreeVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const [cueOne, cueTwo, cueThree, cueFour] = segment.cues;

  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  const fade = (cue: CueTiming, next?: CueTiming) => {
    const fadeIn = interpolate(frame, [cue.relativeStartFrame, cue.relativeStartFrame + 12], [0, 1], clamp);
    const fadeOut = next ? interpolate(frame, [next.relativeStartFrame - 8, next.relativeStartFrame], [1, 0], clamp) : 1;
    return Math.min(fadeIn, fadeOut);
  };

  const reveal = (cue: CueTiming, delay = 10) =>
    spring({ frame: Math.max(0, frame - cue.relativeStartFrame - delay), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const r1 = reveal(cueOne);
  const r1Arrow = spring({ frame: Math.max(0, frame - cueOne.relativeStartFrame - 40), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const r1Runtime = spring({ frame: Math.max(0, frame - cueOne.relativeStartFrame - 60), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const r1Arrow2 = spring({ frame: Math.max(0, frame - cueOne.relativeStartFrame - 90), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const r1Parsed = spring({ frame: Math.max(0, frame - cueOne.relativeStartFrame - 110), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const morph12 = spring({ frame: Math.max(0, frame - cueTwo.relativeStartFrame + 15), fps, config: { damping: 22, stiffness: 60, mass: 1.2 } });
  const r2 = reveal(cueTwo, 15);

  const morph23 = spring({ frame: Math.max(0, frame - cueThree.relativeStartFrame + 15), fps, config: { damping: 22, stiffness: 60, mass: 1.2 } });
  const r3 = reveal(cueThree);
  const r3Arrow = spring({ frame: Math.max(0, frame - cueThree.relativeStartFrame - 30), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
  const r3Ctx = spring({ frame: Math.max(0, frame - cueThree.relativeStartFrame - 50), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const morph34 = spring({ frame: Math.max(0, frame - cueFour.relativeStartFrame + 15), fps, config: { damping: 22, stiffness: 60, mass: 1.2 } });
  const r4 = reveal(cueFour);

  const termLocal = Math.max(0, frame - cueTwo.relativeStartFrame - 30);
  const termLines = ["$ pytest tests/", "", "PASS  tests/parser.test.ts", "PASS  tests/tool-call.test.ts", "FAIL  tests/runtime.test.ts", "", "  ● runtime › should write back result", "    AssertionError: expected writeBack()", "", "Tests:  2 passed, 1 failed"];
  const visibleTermLines = Math.floor(interpolate(termLocal, [0, 120], [0, termLines.length], clamp));

  const contextWriteLocal = Math.max(0, frame - cueThree.relativeStartFrame - 50);
  const contextLines = ["// runtime 写回 context 的内容", "", "tool_result: {", '  exit_code: 1,', '  stdout: "2 passed, 1 failed",', '  stderr: "AssertionError: expected writeBack()"', "}"];
  const visibleCtxLines = Math.floor(interpolate(contextWriteLocal, [0, 80], [0, contextLines.length], clamp));

  const LEFT = 40;
  const TOP = 40;
  const CANVAS_W = 1920 - 80;
  const CANVAS_H = 1080 - 40 - 220;
  const GAP = 16;
  const ARROW_W = 48;
  const RT_W = 280;

  const phase1Opacity = fade(cueOne, cueTwo);
  const phase4Opacity = fade(cueFour);

  const rtLeft = interpolate(morph12, [0, 1], [LEFT + (CANVAS_W - RT_W) / 2, LEFT], clamp);
  const rtTop = interpolate(morph12, [0, 1], [TOP + (CANVAS_H - 280) / 2, TOP], clamp);
  const rtWidth = interpolate(morph12, [0, 1], [RT_W, 240], clamp);
  const rtHeight = interpolate(morph12, [0, 1], [280, 200], clamp);

  const rtOpacityIn = Math.min(r1Runtime, 1);
  const rtOpacity23 = interpolate(morph23, [0, 1], [1, 1], clamp);
  const rtOpacityOut = interpolate(morph34, [0, 1], [1, 0], clamp);
  const rtOpacity = rtOpacityIn * rtOpacity23 * rtOpacityOut;

  const rtStatus = frame < cueTwo.relativeStartFrame ? "parsing" : frame < cueThree.relativeStartFrame ? "executing" : "writing";

  const termLeft = interpolate(morph12, [0, 1], [LEFT, LEFT + 240 + GAP], clamp);
  const termTop = TOP;
  const termWidth = interpolate(morph12, [0, 1], [0, CANVAS_W - 240 - GAP], clamp);
  const termHeight = CANVAS_H;
  const termOpacity = interpolate(morph12, [0.3, 0.8], [0, 1], clamp);

  const termShrinkLeft = interpolate(morph23, [0, 1], [termLeft, LEFT], clamp);
  const termShrinkWidth = interpolate(morph23, [0, 1], [termWidth, (CANVAS_W - RT_W - 2 * ARROW_W - 4 * GAP) / 2], clamp);

  const rtCenterLeft = interpolate(morph23, [0, 1], [rtLeft, LEFT + termShrinkWidth + ARROW_W + 2 * GAP + (RT_W - rtWidth) / 2], clamp);
  const rtCenterTop = interpolate(morph23, [0, 1], [rtTop, TOP + (CANVAS_H - rtHeight) / 2], clamp);

  const ctxLeft = LEFT + (CANVAS_W + RT_W) / 2 + ARROW_W + 2 * GAP;
  const ctxWidth = (CANVAS_W - RT_W - 2 * ARROW_W - 4 * GAP) / 2;

  const showPhase1Side = phase1Opacity > 0.05 && morph12 < 0.1;
  const showPhase23 = morph12 > 0.05 && morph34 < 0.95;
  const showPhase4 = morph34 > 0.05;

  return (
    <>
      <GridBackdrop />
      <div style={{ position: "relative", width: "100%", height: "100%" }}>

        {/* Phase 1 side panels: model output (left) and parsed action (right) */}
        {showPhase1Side && (
          <>
            <WindowFrame
              title="model output (text)"
              style={{
                position: "absolute", left: LEFT, top: TOP,
                width: (CANVAS_W - RT_W - 2 * ARROW_W - 4 * GAP) / 2,
                height: CANVAS_H,
                opacity: r1 * phase1Opacity,
                transform: `translateX(${interpolate(r1, [0, 1], [-30, 0])}px)`,
              }}
            >
              <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)", padding: 24, fontFamily: THEME.fonts.code, fontSize: 18, lineHeight: 1.6 }}>
                <pre style={{ margin: 0, whiteSpace: "pre-wrap" }}>
                  <span style={{ color: THEME.colors.textSecondary }}>{"好的，让我先执行测试：\n\n"}</span>
                  <span style={{ color: ACCENT, fontWeight: 600 }}>{"{\n  \"type\": \"tool_use\",\n  \"name\": \"bash\",\n  \"command\": \"pytest tests/\"\n}"}</span>
                </pre>
              </div>
            </WindowFrame>

            <div style={{ position: "absolute", left: LEFT + (CANVAS_W - RT_W - 2 * ARROW_W - 4 * GAP) / 2 + GAP, top: TOP + CANVAS_H / 2 - 10, opacity: r1Arrow * phase1Opacity }}>
              <FlowArrow progress={r1Arrow} length={ARROW_W} />
            </div>

            <div style={{ position: "absolute", left: LEFT + CANVAS_W - (CANVAS_W - RT_W - 2 * ARROW_W - 4 * GAP) / 2 - ARROW_W - GAP, top: TOP + CANVAS_H / 2 - 10, opacity: r1Arrow2 * phase1Opacity }}>
              <FlowArrow progress={r1Arrow2} length={ARROW_W} />
            </div>

            <WindowFrame
              title="parsed action"
              style={{
                position: "absolute",
                left: LEFT + CANVAS_W - (CANVAS_W - RT_W - 2 * ARROW_W - 4 * GAP) / 2,
                top: TOP, width: (CANVAS_W - RT_W - 2 * ARROW_W - 4 * GAP) / 2,
                height: CANVAS_H,
                opacity: r1Parsed * phase1Opacity,
                transform: `translateX(${interpolate(r1Parsed, [0, 1], [30, 0])}px)`,
              }}
            >
              <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.24)", border: "1px solid rgba(63, 185, 80, 0.25)", padding: 24, fontFamily: THEME.fonts.code, fontSize: 20, lineHeight: 1.6 }}>
                <div style={{ color: THEME.colors.textSecondary }}>// 解析出的真实动作</div>
                <div style={{ color: THEME.colors.textSecondary }}> </div>
                <div style={{ color: "#3FB950", fontWeight: 600 }}>tool:    bash</div>
                <div style={{ color: "#3FB950", fontWeight: 600 }}>command: pytest tests/</div>
                <div style={{ color: THEME.colors.textSecondary }}> </div>
                <div style={{ color: "#7EE787" }}>→ 文本变成系统调用</div>
              </div>
            </WindowFrame>
          </>
        )}

        {/* Runtime block — persistent, morphs position across phases 1→2→3 */}
        {(rtOpacity > 0.01) && (
          <RuntimeBlock
            status={rtStatus}
            style={{
              position: "absolute",
              left: morph23 > 0.05 ? rtCenterLeft : rtLeft,
              top: morph23 > 0.05 ? rtCenterTop : rtTop,
              width: rtWidth,
              height: rtHeight,
              opacity: rtOpacity,
              transform: `scale(${interpolate(rtOpacityIn, [0, 1], [0.85, 1])})`,
            }}
          />
        )}

        {/* Execution step list — appears in phase 2, fades in phase 3 */}
        {showPhase23 && morph23 < 0.7 && (
          <div
            style={{
              position: "absolute", left: LEFT, top: TOP + 220,
              width: 240, height: CANVAS_H - 220,
              borderRadius: 18,
              background: "rgba(63, 185, 80, 0.06)",
              border: "1px solid rgba(63, 185, 80, 0.15)",
              padding: 20,
              display: "flex", flexDirection: "column", gap: 10,
              fontFamily: THEME.fonts.code, fontSize: 15,
              color: THEME.colors.textSecondary,
              opacity: interpolate(morph12, [0.5, 0.9], [0, 1], clamp) * interpolate(morph23, [0, 0.5], [1, 0], clamp),
            }}
          >
            <div style={{ color: "#3FB950", fontWeight: 600 }}>执行流程</div>
            <div>1. 解析 tool call</div>
            <div style={{ color: "#7EE787" }}>2. 送进终端 ←</div>
            <div>3. 捕获输出</div>
            <div>4. 写回 context</div>
          </div>
        )}

        {/* Terminal — expands in phase 2, shrinks to left in phase 3 */}
        {showPhase23 && (
          <WindowFrame
            title="Terminal"
            style={{
              position: "absolute",
              left: morph23 > 0.05 ? termShrinkLeft : termLeft,
              top: termTop,
              width: morph23 > 0.05 ? termShrinkWidth : termWidth,
              height: termHeight,
              opacity: termOpacity * interpolate(morph34, [0, 1], [1, 0], clamp),
              transform: `translateY(${interpolate(r2, [0, 1], [30, 0])}px)`,
            }}
            headerRight={
              morph23 < 0.5 ? (
                <div style={{ padding: "6px 14px", borderRadius: 999, background: "#7EE78722", border: "1px solid #7EE78744", fontFamily: THEME.fonts.code, fontSize: 16, color: "#7EE787" }}>
                  running
                </div>
              ) : undefined
            }
          >
            <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.4)", border: "1px solid rgba(255,255,255,0.08)", padding: 24, fontFamily: THEME.fonts.code, fontSize: interpolate(morph23, [0, 1], [22, 17], clamp), lineHeight: 1.6 }}>
              {termLines.slice(0, morph23 > 0.3 ? termLines.length : visibleTermLines).map((line, i) => (
                <div key={`tl-${i}`} style={{ color: line.includes("FAIL") || line.includes("Assertion") ? "#FF7B72" : line.includes("PASS") ? "#7EE787" : THEME.colors.textPrimary, minHeight: line === "" ? (morph23 > 0.3 ? 6 : 12) : undefined }}>
                  {line}
                </div>
              ))}
            </div>
          </WindowFrame>
        )}

        {/* Phase 3 arrows and context */}
        {morph23 > 0.3 && morph34 < 0.95 && (
          <>
            <div style={{
              position: "absolute",
              left: LEFT + termShrinkWidth + GAP,
              top: TOP + CANVAS_H / 2 - 10,
              opacity: r3Arrow * interpolate(morph34, [0, 1], [1, 0], clamp),
            }}>
              <FlowArrow progress={r3Arrow} length={ARROW_W} />
            </div>
            <div style={{
              position: "absolute",
              left: ctxLeft - ARROW_W - GAP,
              top: TOP + CANVAS_H / 2 - 10,
              opacity: r3Arrow * interpolate(morph34, [0, 1], [1, 0], clamp),
            }}>
              <FlowArrow progress={r3Arrow} length={ARROW_W} />
            </div>
            <WindowFrame
              title="context (updated)"
              style={{
                position: "absolute", left: ctxLeft, top: TOP,
                width: ctxWidth, height: CANVAS_H,
                opacity: r3Ctx * interpolate(morph34, [0, 1], [1, 0], clamp),
                transform: `translateX(${interpolate(r3Ctx, [0, 1], [20, 0])}px)`,
              }}
            >
              <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.24)", border: "1px solid rgba(63, 185, 80, 0.2)", padding: 22, fontFamily: THEME.fonts.code, fontSize: 18, lineHeight: 1.6 }}>
                {contextLines.slice(0, visibleCtxLines).map((line, i) => (
                  <div key={`cl-${i}`} style={{ color: line.startsWith("//") ? "#79C0FF" : line.includes("stderr") || line.includes("exit_code: 1") ? "#FF7B72" : THEME.colors.textPrimary, minHeight: line === "" ? 6 : undefined }}>
                    {line}
                  </div>
                ))}
              </div>
            </WindowFrame>
          </>
        )}

        {/* Phase 4: Loop — model sees evidence, emits next actions */}
        {showPhase4 && (
          <div
            style={{
              position: "absolute", left: LEFT, right: LEFT, top: TOP, bottom: 220,
              display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 32,
              opacity: phase4Opacity,
            }}
          >
            <div style={{ fontFamily: THEME.fonts.body, fontSize: 24, color: THEME.colors.textSecondary, opacity: r4, textAlign: "center" }}>
              模型看到新证据，输出下一步动作：
            </div>
            <div style={{ display: "flex", gap: 24, alignItems: "center" }}>
              {["read_file(src/runtime.ts)", "apply_patch(fix)", "bash(pytest tests/)"].map((action, i) => {
                const stagger = spring({ frame: Math.max(0, frame - cueFour.relativeStartFrame - 30 - i * 20), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
                return (
                  <div
                    key={`a4-${i}`}
                    style={{
                      padding: "24px 36px", borderRadius: 20,
                      background: i === 2 ? `${ACCENT}22` : "rgba(255,255,255,0.06)",
                      border: `1px solid ${i === 2 ? `${ACCENT}55` : "rgba(255,255,255,0.12)"}`,
                      fontFamily: THEME.fonts.code, fontSize: 24, fontWeight: 600,
                      color: i === 2 ? ACCENT : THEME.colors.textPrimary,
                      opacity: stagger,
                      transform: `translateY(${interpolate(stagger, [0, 1], [30, 0])}px)`,
                    }}
                  >
                    {action}
                  </div>
                );
              })}
            </div>
            <div
              style={{
                fontFamily: THEME.fonts.body, fontSize: 28, fontWeight: 700,
                color: ACCENT, opacity: r4, textAlign: "center",
                marginTop: 16,
              }}
            >
              loop 转起来了 →
            </div>
          </div>
        )}

      </div>
    </>
  );
};

