const LoopNode: React.FC<{
  label: string;
  icon: string;
  x: number;
  y: number;
  width: number;
  height: number;
  highlight?: boolean;
  opacity: number;
  accentColor?: string;
}> = ({ label, icon, x, y, width, height, highlight, opacity, accentColor }) => {
  const bg = highlight ? "rgba(63, 185, 80, 0.15)" : "rgba(255,255,255,0.05)";
  const borderColor = highlight ? "rgba(63, 185, 80, 0.5)" : "rgba(255,255,255,0.12)";
  const textColor = highlight ? "#3FB950" : (accentColor || THEME.colors.textPrimary);

  return (
    <div
      style={{
        position: "absolute", left: x, top: y, width, height,
        borderRadius: 22,
        background: bg,
        border: `2px solid ${borderColor}`,
        boxShadow: highlight ? "0 0 30px rgba(63, 185, 80, 0.1)" : "none",
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8,
        opacity,
      }}
    >
      <div style={{ fontSize: 32 }}>{icon}</div>
      <div style={{ fontFamily: THEME.fonts.code, fontSize: 20, fontWeight: 700, color: textColor, textAlign: "center" }}>
        {label}
      </div>
    </div>
  );
};

const LoopArrow: React.FC<{
  x1: number; y1: number; x2: number; y2: number;
  opacity: number; color?: string;
}> = ({ x1, y1, x2, y2, opacity, color = `${ACCENT}88` }) => {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.sqrt(dx * dx + dy * dy);
  const angle = Math.atan2(dy, dx) * (180 / Math.PI);

  return (
    <div
      style={{
        position: "absolute", left: x1, top: y1,
        width: len, height: 0,
        transform: `rotate(${angle}deg)`,
        transformOrigin: "0 0",
        opacity,
      }}
    >
      <div style={{ width: len - 10, height: 3, background: `linear-gradient(90deg, ${color}, ${color})`, borderRadius: 999 }} />
      <div style={{
        position: "absolute", right: 0, top: -5,
        width: 0, height: 0,
        borderTop: "6px solid transparent", borderBottom: "6px solid transparent",
        borderLeft: `9px solid ${color}`,
      }} />
    </div>
  );
};

const SegmentFourVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const cueTwoStart = segment.cues[1].relativeStartFrame;

  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  const loopNodes = [
    { label: "User", icon: "👤", x: 160, y: 40 },
    { label: "LLM", icon: "🧠", x: 760, y: 40 },
    { label: "Runtime", icon: "⚙", x: 1360, y: 40, highlight: true },
    { label: "Terminal\nFiles\nPatch", icon: "💻", x: 1360, y: 380 },
    { label: "Context", icon: "📋", x: 760, y: 380 },
  ];

  const nodeW = 220;
  const nodeH = 140;

  const staggerReveals = loopNodes.map((_, i) =>
    spring({ frame: Math.max(0, frame - 10 - i * 12), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } })
  );
  const arrowReveals = loopNodes.map((_, i) =>
    spring({ frame: Math.max(0, frame - 30 - i * 12), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } })
  );

  const rtHighlight = spring({ frame: Math.max(0, frame - 100), fps, config: { damping: 20, stiffness: 70, mass: 1 } });

  const morphToPreview = spring({ frame: Math.max(0, frame - cueTwoStart + 15), fps, config: { damping: 22, stiffness: 60, mass: 1.2 } });
  const previewReveal = spring({ frame: Math.max(0, frame - cueTwoStart - 10), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const loopScale = interpolate(morphToPreview, [0, 1], [1, 0.65], clamp);
  const loopY = interpolate(morphToPreview, [0, 1], [0, -120], clamp);
  const loopOpacity = interpolate(morphToPreview, [0, 1], [1, 0.7], clamp);

  return (
    <>
      <GridBackdrop />
      <div style={{ position: "relative", width: "100%", height: "100%" }}>

        {/* Loop diagram */}
        <div
          style={{
            position: "absolute", left: 40, right: 40, top: 40, bottom: 220,
            transform: `scale(${loopScale}) translateY(${loopY}px)`,
            transformOrigin: "center top",
            opacity: loopOpacity,
          }}
        >
          {/* Arrows between nodes */}
          <LoopArrow x1={loopNodes[0].x + nodeW} y1={loopNodes[0].y + nodeH / 2} x2={loopNodes[1].x} y2={loopNodes[1].y + nodeH / 2} opacity={arrowReveals[0]} color={`${ACCENT}66`} />
          <LoopArrow x1={loopNodes[1].x + nodeW} y1={loopNodes[1].y + nodeH / 2} x2={loopNodes[2].x} y2={loopNodes[2].y + nodeH / 2} opacity={arrowReveals[1]} color={`${ACCENT}66`} />
          <LoopArrow x1={loopNodes[2].x + nodeW / 2} y1={loopNodes[2].y + nodeH} x2={loopNodes[3].x + nodeW / 2} y2={loopNodes[3].y} opacity={arrowReveals[2]} color="rgba(63, 185, 80, 0.5)" />
          <LoopArrow x1={loopNodes[3].x} y1={loopNodes[3].y + nodeH / 2} x2={loopNodes[4].x + nodeW} y2={loopNodes[4].y + nodeH / 2} opacity={arrowReveals[3]} color={`${ACCENT}66`} />
          <LoopArrow x1={loopNodes[4].x} y1={loopNodes[4].y + nodeH / 2} x2={loopNodes[0].x + nodeW / 2 + 60} y2={loopNodes[0].y + nodeH + 30} opacity={arrowReveals[4]} color={`${ACCENT}66`} />

          {/* Nodes */}
          {loopNodes.map((node, i) => (
            <LoopNode
              key={`ln-${i}`}
              label={node.label}
              icon={node.icon}
              x={node.x}
              y={node.y}
              width={nodeW}
              height={nodeH}
              highlight={node.highlight}
              opacity={staggerReveals[i]}
              accentColor={i === 1 ? ACCENT : undefined}
            />
          ))}

          {/* Runtime highlight label */}
          <div
            style={{
              position: "absolute",
              left: loopNodes[2].x,
              top: loopNodes[2].y + nodeH + 12,
              width: nodeW,
              textAlign: "center",
              fontFamily: THEME.fonts.body,
              fontSize: 18,
              color: "#3FB950",
              fontWeight: 600,
              opacity: rtHighlight,
            }}
          >
            token → 真实动作
          </div>

          {/* Center summary */}
          <div
            style={{
              position: "absolute",
              left: 400, top: 180,
              width: 920, textAlign: "center",
              fontFamily: THEME.fonts.title,
              fontSize: 32,
              fontWeight: 800,
              color: THEME.colors.textPrimary,
              lineHeight: 1.3,
              opacity: rtHighlight,
            }}
          >
            模型续写 token，Runtime 兑现成动作
          </div>
        </div>

        {/* Preview cards — slide up from bottom */}
        {morphToPreview > 0.1 && (
          <div
            style={{
              position: "absolute",
              left: 60, right: 60,
              bottom: 240,
              display: "grid",
              gridTemplateColumns: "repeat(3, 1fr)",
              gap: 24,
              opacity: previewReveal,
              transform: `translateY(${interpolate(previewReveal, [0, 1], [40, 0])}px)`,
            }}
          >
            {[
              { code: S01E01_EPISODE.nextEpisodeCode, title: "Tool Use", cn: "给 Agent 装上手和脚", icon: "🔧" },
              { code: "S01E03", title: "Subagent", cn: "把大循环拆成小任务", icon: "🔄" },
              { code: "S01E04", title: "Memory", cn: "让有用的状态跨轮留存", icon: "🧠" },
            ].map((item, index) => {
              const cardStagger = spring({ frame: Math.max(0, frame - cueTwoStart - 20 - index * 15), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
              return (
                <div
                  key={item.title}
                  style={{
                    ...shellPanel,
                    padding: "28px 24px",
                    display: "flex",
                    flexDirection: "column",
                    gap: 14,
                    background: index === 0 ? `${ACCENT}14` : "rgba(13,17,23,0.85)",
                    border: `1px solid ${index === 0 ? `${ACCENT}44` : "rgba(255,255,255,0.08)"}`,
                    opacity: cardStagger,
                    transform: `translateY(${interpolate(cardStagger, [0, 1], [20, 0])}px)`,
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <div style={{ fontSize: 28 }}>{item.icon}</div>
                    <div style={{ fontFamily: THEME.fonts.code, fontSize: 16, letterSpacing: 1, textTransform: "uppercase", color: `${ACCENT}CC` }}>
                      {item.code} · {item.title}
                    </div>
                  </div>
                  <div style={{ fontFamily: THEME.fonts.title, fontSize: 24, fontWeight: 700, lineHeight: 1.3 }}>
                    {item.cn}
                  </div>
                </div>
              );
            })}
          </div>
        )}

      </div>
    </>
  );
};

