type Variant = "normal" | "season_finale" | "series_finale";

export interface OutroProps {
  seriesName: string;
  seriesAccentColor: string;
  variant: Variant;
  nextEpisodeCode?: string;
  nextEpisodeTitle?: string;
}

const subtextFor = (props: OutroProps): string | undefined => {
  switch (props.variant) {
    case "normal":
      return props.nextEpisodeCode && props.nextEpisodeTitle
        ? `下一期：${props.nextEpisodeCode} · ${props.nextEpisodeTitle}`
        : undefined;
    case "season_finale":
      return "本季完结 · 下一季即将上线";
    case "series_finale":
      return "本系列完结 · 感谢观看";
  }
};

