    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleReveal = spring({
    frame: Math.max(0, frame - 10),
    fps,
    config: { damping: 16, stiffness: 95, mass: 0.92 },
  });
  const subtextReveal = spring({
    frame: Math.max(0, frame - 24),
    fps,
