import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { THEME, OUTRO_FRAMES } from "../theme";

type Variant = "normal" | "season_finale" | "series_finale";

export interface OutroProps {
  seriesName: string;
  seriesAccentColor: string;
  variant: Variant;
  nextEpisodeCode?: string;
  nextEpisodeTitle?: string;
}

export const Outro: React.FC<OutroProps> = (props) => {
  const { seriesAccentColor } = props;
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  const fadeIn = interpolate(frame, [0, 12], [0, 1], clamp);
  const titleReveal = spring({ frame: Math.max(0, frame - 8), fps, config: { damping: 16, stiffness: 90, mass: 0.92 } });
  const nextReveal = spring({ frame: Math.max(0, frame - 22), fps, config: { damping: 17, stiffness: 95, mass: 0.9 } });
  const footerReveal = spring({ frame: Math.max(0, frame - 36), fps, config: { damping: 17, stiffness: 98, mass: 0.88 } });
  const lineScale = interpolate(frame, [20, 48], [0, 1], clamp);
  const fadeOut = interpolate(frame, [OUTRO_FRAMES - 12, OUTRO_FRAMES], [1, 0], clamp);

  const nextEpisodeLine =
    props.nextEpisodeCode && props.nextEpisodeTitle
      ? `下一期：${props.nextEpisodeCode} · ${props.nextEpisodeTitle}`
      : props.variant === "season_finale"
        ? "本季完结 · 下一季即将上线"
        : "本系列完结 · 感谢观看";

  return (
    <AbsoluteFill
      style={{
        backgroundColor: THEME.colors.bg,
        color: THEME.colors.textPrimary,
        opacity: Math.min(fadeIn, fadeOut),
      }}
    >
      <AbsoluteFill
        style={{
          backgroundImage: `radial-gradient(circle at 50% 40%, ${seriesAccentColor}18 0%, transparent 40%)`,
        }}
      />
      <div
        style={{
          position: "absolute", inset: 0,
          display: "flex", alignItems: "center", justifyContent: "center",
          padding: 96,
        }}
      >
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 22, textAlign: "center" }}>
          <div
            style={{
              fontFamily: THEME.fonts.title, fontSize: 72, fontWeight: 800,
              lineHeight: 1.1, letterSpacing: "-0.03em",
              opacity: titleReveal,
              transform: `translateY(${interpolate(titleReveal, [0, 1], [24, 0])}px)`,
            }}
          >
            感谢观看
          </div>

          <div
            style={{
              width: 240, height: 2, borderRadius: 999,
              background: `linear-gradient(90deg, transparent, ${seriesAccentColor}AA, transparent)`,
              transformOrigin: "center", transform: `scaleX(${lineScale})`,
            }}
          />

          <div
            style={{
              fontFamily: THEME.fonts.body, fontSize: 26,
              color: THEME.colors.textSecondary, lineHeight: 1.4,
              opacity: nextReveal,
              transform: `translateY(${interpolate(nextReveal, [0, 1], [14, 0])}px)`,
            }}
          >
            {nextEpisodeLine}
          </div>

          <div
            style={{
              fontFamily: THEME.fonts.code, fontSize: 16, letterSpacing: 2,
              color: `${seriesAccentColor}AA`, marginTop: 12,
              opacity: footerReveal,
              transform: `translateY(${interpolate(footerReveal, [0, 1], [10, 0])}px)`,
            }}
          >
            © 鳄鱼骑士卡皮巴拉
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export const OUTRO_DURATION = OUTRO_FRAMES;

