  const cueTwoStart = cueTwo.relativeStartFrame;
  const cueThreeStart = cueThree.relativeStartFrame;

  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  const fade = (cue: CueTiming, next?: CueTiming) => {
    const fadeIn = interpolate(frame, [cue.relativeStartFrame, cue.relativeStartFrame + 12], [0, 1], clamp);
    const fadeOut = next ? interpolate(frame, [next.relativeStartFrame - 8, next.relativeStartFrame], [1, 0], clamp) : 1;
    return Math.min(fadeIn, fadeOut);
  };
  const fade1 = fade(cueOne, cueTwo);
  const fade2 = fade(cueTwo, cueThree);
  const fade3 = fade(cueThree);

  const r1 = spring({ frame: Math.max(0, frame - 10), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });
