const SegmentFourVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const cues = segment.cues;

  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

  const fade = (cueIdx: number) => {
    const cue = cues[cueIdx];
    const next = cues[cueIdx + 1];
    const fadeIn = interpolate(frame, [cue.relativeStartFrame, cue.relativeStartFrame + 12], [0, 1], clamp);
    const fadeOut = next ? interpolate(frame, [next.relativeStartFrame - 8, next.relativeStartFrame], [1, 0], clamp) : 1;
    return Math.min(fadeIn, fadeOut);
  };

  const staggerFrom = (startFrame: number, idx: number) =>
    spring({ frame: Math.max(0, frame - startFrame - idx * 10), fps, config: { damping: 16, stiffness: 90, mass: 0.9 } });

  const convergedActions = [
    { name: "Read", desc: "读取文件内容" },
    { name: "Write / Edit", desc: "编辑或创建文件" },
    { name: "Bash / Shell", desc: "执行终端命令" },
    { name: "Grep / Search", desc: "搜索代码库" },
    { name: "Glob / List", desc: "查找文件和目录" },
    { name: "WebSearch", desc: "搜索互联网信息" },
  ];

  const cursorTools = ["Read", "Edit", "Shell", "Glob", "Grep", "WebSearch", "Browser"];
  const claudeTools = ["Read", "Write", "Bash", "Glob", "WebFetch", "Agent", "Grep"];

  const r1 = staggerFrom(10, 0);
  const r1Llm = staggerFrom(30, 0);
  const r1Rt = staggerFrom(60, 0);
  const r1Act = staggerFrom(90, 0);

  return (
    <>
      <GridBackdrop />
      <div style={{ position: "relative", width: "100%", height: "100%" }}>

        {/* Phase 1: Loop recap */}
        <div style={{
          position: "absolute", left: 40, right: 40, top: 40, bottom: 220,
          display: "grid", gridTemplateColumns: "1fr auto 260px auto 1fr auto 1fr", gap: 12, alignItems: "center",
          opacity: fade(0), pointerEvents: fade(0) < 0.1 ? "none" : "auto",
        }}>
          <WindowFrame title="prompt (text)" style={{ opacity: r1, transform: `translateX(${interpolate(r1, [0, 1], [-30, 0])}px)` }}>
            <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,255,255,0.08)", padding: 20, fontFamily: THEME.fonts.code, fontSize: 18, lineHeight: 1.6 }}>
              <div style={{ color: "#79C0FF" }}>&lt;user&gt;</div>
              <div style={{ color: THEME.colors.textPrimary }}>  帮我跑一下测试</div>
              <div style={{ color: "#79C0FF" }}>&lt;/user&gt;</div>
            </div>
          </WindowFrame>
          <FlowArrow progress={r1Llm} length={40} />
          <LlmBlock style={{ width: "100%", minHeight: 280, opacity: r1Llm, transform: `scale(${interpolate(r1Llm, [0, 1], [0.85, 1])})` }} />
          <FlowArrow progress={r1Rt} length={40} />
          <RuntimeBlock status="idle" style={{ width: "100%", minHeight: 280, opacity: r1Rt, transform: `scale(${interpolate(r1Rt, [0, 1], [0.85, 1])})` }} />
          <FlowArrow progress={r1Act} length={40} />
          <WindowFrame title="Terminal / Files" style={{ opacity: r1Act, transform: `translateX(${interpolate(r1Act, [0, 1], [30, 0])}px)` }}>
            <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.32)", border: "1px solid rgba(255,255,255,0.08)", padding: 20, fontFamily: THEME.fonts.code, fontSize: 18, lineHeight: 1.6 }}>
              <div style={{ color: "#7EE787" }}>$ pytest tests/</div>
              <div style={{ color: THEME.colors.textSecondary }}>// runtime 兑现成真实动作</div>
            </div>
          </WindowFrame>
        </div>

        {/* Phase 2: Converged actions grid */}
        <div style={{
          position: "absolute", left: 40, right: 40, top: 40, bottom: 220,
          display: "grid", gridTemplateColumns: "280px 1fr", gap: 24, alignItems: "stretch",
          opacity: fade(1), pointerEvents: fade(1) < 0.1 ? "none" : "auto",
        }}>
          <RuntimeBlock status="idle" style={{ opacity: staggerFrom(cues[1].relativeStartFrame, 0) }} />
          <WindowFrame title="converged runtime actions" style={{ opacity: staggerFrom(cues[1].relativeStartFrame, 0) }}>
            <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.24)", border: "1px solid rgba(63,185,80,0.2)", padding: 20 }}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                {convergedActions.map((a, i) => {
                  const s = staggerFrom(cues[1].relativeStartFrame + 15, i);
                  return (
                    <div key={a.name} style={{
                      padding: "14px 18px", borderRadius: 14,
                      background: "rgba(63,185,80,0.08)", border: "1px solid rgba(63,185,80,0.2)",
                      display: "flex", flexDirection: "column", gap: 4,
                      opacity: s, transform: `translateY(${interpolate(s, [0, 1], [12, 0])}px)`,
                    }}>
                      <div style={{ fontFamily: THEME.fonts.code, fontSize: 18, fontWeight: 600, color: "#3FB950" }}>{a.name}</div>
                      <div style={{ fontFamily: THEME.fonts.body, fontSize: 15, color: THEME.colors.textSecondary }}>{a.desc}</div>
                    </div>
                  );
                })}
              </div>
              <div style={{ marginTop: 14, padding: "10px 16px", borderRadius: 12, background: `${ACCENT}10`, border: `1px solid ${ACCENT}25`, fontFamily: THEME.fonts.code, fontSize: 15, color: THEME.colors.textSecondary, textAlign: "center" }}>
                Cursor · Claude Code · Copilot · Windsurf — 基本一致
              </div>
            </div>
          </WindowFrame>
        </div>

        {/* Phase 3: Each vendor's builtin tools */}
        <div style={{
          position: "absolute", left: 40, right: 40, top: 40, bottom: 220,
          display: "grid", gridTemplateColumns: "1fr 1fr", gap: 28, alignItems: "stretch",
          opacity: fade(2), pointerEvents: fade(2) < 0.1 ? "none" : "auto",
        }}>
          <WindowFrame title="Cursor · Builtin Tools" style={{ opacity: staggerFrom(cues[2].relativeStartFrame, 0) }}>
            <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.24)", border: `1px solid ${ACCENT}30`, padding: 24, display: "flex", flexDirection: "column", gap: 10 }}>
              {cursorTools.map((t, i) => {
                const s = staggerFrom(cues[2].relativeStartFrame + 20, i);
                return (
                  <div key={t} style={{
                    padding: "10px 16px", borderRadius: 12,
                    background: `${ACCENT}0A`, border: `1px solid ${ACCENT}20`,
                    fontFamily: THEME.fonts.code, fontSize: 20, color: THEME.colors.textPrimary,
                    opacity: s, transform: `translateX(${interpolate(s, [0, 1], [-12, 0])}px)`,
                  }}>
                    {t}
                  </div>
                );
              })}
            </div>
          </WindowFrame>
          <WindowFrame title="Claude Code · Builtin Tools" style={{ opacity: staggerFrom(cues[2].relativeStartFrame + 5, 0) }}>
            <div style={{ flex: 1, borderRadius: 18, background: "rgba(0,0,0,0.24)", border: "1px solid rgba(255,180,100,0.25)", padding: 24, display: "flex", flexDirection: "column", gap: 10 }}>
              {claudeTools.map((t, i) => {
                const s = staggerFrom(cues[2].relativeStartFrame + 25, i);
                return (
                  <div key={t} style={{
                    padding: "10px 16px", borderRadius: 12,
                    background: "rgba(255,180,100,0.06)", border: "1px solid rgba(255,180,100,0.18)",
                    fontFamily: THEME.fonts.code, fontSize: 20, color: THEME.colors.textPrimary,
                    opacity: s, transform: `translateX(${interpolate(s, [0, 1], [12, 0])}px)`,
                  }}>
                    {t}
                  </div>
                );
              })}
            </div>
          </WindowFrame>
        </div>

        {/* Phase 4: Tool use as trained primitive */}
        <div style={{
          position: "absolute", left: 60, right: 60, top: 60, bottom: 240,
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 36,
          opacity: fade(3), pointerEvents: fade(3) < 0.1 ? "none" : "auto",
        }}>
          <LlmBlock style={{
            width: 320, minHeight: 280,
            opacity: staggerFrom(cues[3].relativeStartFrame, 0),
            transform: `scale(${interpolate(staggerFrom(cues[3].relativeStartFrame, 0), [0, 1], [0.85, 1])})`,
          }} />
          <div style={{
            fontFamily: THEME.fonts.title, fontSize: 42, fontWeight: 800, textAlign: "center",
            lineHeight: 1.3, maxWidth: 900,
            opacity: staggerFrom(cues[3].relativeStartFrame + 30, 0),
            transform: `translateY(${interpolate(staggerFrom(cues[3].relativeStartFrame + 30, 0), [0, 1], [20, 0])}px)`,
          }}>
            Tool Use 能力 → 模型权重内化
          </div>
          <div style={{
            fontFamily: THEME.fonts.body, fontSize: 24, color: THEME.colors.textSecondary, textAlign: "center",
            opacity: staggerFrom(cues[3].relativeStartFrame + 50, 0),
          }}>
            Agent 时代最基本的构建原语
          </div>
        </div>

        {/* Phase 5: Preview next episode */}
        <div style={{
          position: "absolute", left: 60, right: 60, top: 60, bottom: 240,
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 28,
          opacity: fade(4), pointerEvents: fade(4) < 0.1 ? "none" : "auto",
        }}>
          <div style={{
            fontFamily: THEME.fonts.body, fontSize: 22, color: THEME.colors.textSecondary,
            opacity: staggerFrom(cues[4].relativeStartFrame, 0), textAlign: "center",
          }}>
            不同厂家、不同内置工具 — 模型如何正确识别？
          </div>
          <WindowFrame
            title={`${S01E01_EPISODE.nextEpisodeCode} · 下一期`}
            style={{
              width: 700,
              opacity: staggerFrom(cues[4].relativeStartFrame + 15, 0),
              transform: `translateY(${interpolate(staggerFrom(cues[4].relativeStartFrame + 15, 0), [0, 1], [20, 0])}px)`,
              background: `rgba(88,166,255,0.08)`,
              border: `1px solid ${ACCENT}44`,
            }}
          >
            <div style={{
              flex: 1, borderRadius: 18, background: `${ACCENT}10`,
              border: `1px solid ${ACCENT}30`, padding: 32,
              display: "flex", alignItems: "center", justifyContent: "center",
