              <div style={{ fontFamily: THEME.fonts.title, fontSize: 36, fontWeight: 700, lineHeight: 1.3, textAlign: "center" }}>
                大模型的系统提示词和启动机制
              </div>
            </div>
          </WindowFrame>
        </div>

      </div>
    </>
  );
};

