const toolPulseSpring = (
  frame: number,
  fps: number,
  active: boolean,
  activeFrame: number,
  cardIdx: number,
) => {
  if (!active) return 0;
  const cardStart = activeFrame + cardIdx * 5;
  const localFrame = frame - cardStart;
  if (localFrame < 0) return 0;
  return spring({
    frame: localFrame,
    fps,
    config: { damping: 12, stiffness: 110, mass: 0.7 },
  });
};

