const toolPulseSpring = (
  frame: number,
  fps: number,
  active: boolean,
  activeFrame: number,
  cardIdx: number,
) => {
  if (!active) return 0;
  const cardStart = activeFrame + cardIdx * 5;
  const localFrame = frame - cardStart;
  if (localFrame < 0) return 0;
  return spring({
    frame: localFrame,
    fps,
    config: { damping: 14, stiffness: 160, mass: 0.55 },
  });
};

const accentWithAlpha = (accent: string, alpha: number) => {
  const hex = accent.replace("#", "").slice(0, 6);
  const a = Math.round(alpha * 255)
    .toString(16)
    .padStart(2, "0");
  return `#${hex}${a}`;
};

