const SegmentOneVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const cues = segment.cues;
  const cueOpacities = cues.map((_, index) => useCueOpacity(frame, cues, index));

  const c0 = cues[0]?.relativeStartFrame ?? 0;
  const c0Dur = cues[0]?.durationInFrames ?? 300;
  const c1 = cues[1]?.relativeStartFrame ?? 0;
  const c1Dur = cues[1]?.durationInFrames ?? 400;
  const c2 = cues[2]?.relativeStartFrame ?? 0;
  const c2Dur = cues[2]?.durationInFrames ?? 400;

  // seg1-01 pipe segments (6 pipes):
  // "你有没有遇到过这种情况？|你让 agent 帮你做一件事——|比如给你的网站加一个暗色模式。|它开始干了，改了几个文件，|进展挺顺利的。|但这个时候你有别的事，走开了。"
  const c0Progress = interpolate(frame, [c0, c0 + c0Dur], [0, 1], clamp);
  const chatAppear = stagger(frame, fps, c0, 0);
  const darkModeWord = interpolate(c0Progress, [0.28, 0.42], [0, 1], clamp); // "暗色模式" ~pipe 3
  const siteAppear = interpolate(c0Progress, [0.42, 0.55], [0, 1], clamp); // "它开始干了" ~pipe 4
  const filesEdited = interpolate(c0Progress, [0.55, 0.72], [0, 1], clamp); // "改了几个文件"
