const SegmentTwoVisual: React.FC<{ segment: SegmentTiming }> = ({ segment }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const cues = segment.cues;
  const cueOpacities = cues.map((_, index) => useCueOpacity(frame, cues, index));

  const c0 = cues[0]?.relativeStartFrame ?? 0;
  const c0Dur = cues[0]?.durationInFrames ?? 200;
  const c1 = cues[1]?.relativeStartFrame ?? 0;
  const c1Dur = cues[1]?.durationInFrames ?? 300;
  const c2 = cues[2]?.relativeStartFrame ?? 0;
  const c2Dur = cues[2]?.durationInFrames ?? 300;

  // seg2-01: "问题出在哪？|回到我们前两集讲过的工作循环。|Agent 每一轮做三件事——|看当前上下文，选下一步，|把结果写回去。"
  const c0Progress = interpolate(frame, [c0, c0 + c0Dur], [0, 1], clamp);
  const loopMention = interpolate(c0Progress, [0.2, 0.4], [0, 1], clamp);
  const step1 = interpolate(c0Progress, [0.5, 0.62], [0, 1], clamp);
  const step2 = interpolate(c0Progress, [0.62, 0.74], [0, 1], clamp);
  const step3 = interpolate(c0Progress, [0.74, 0.88], [0, 1], clamp);

  // seg2-02: "关键在看当前上下文。|当你的对话很长以后，|系统会自动压缩它——|把早期的对话变成一段摘要，|具体的步骤细节就丢了。|这不是 bug，|是所有 agent 都有的机制，|因为上下文窗口是有限的。"
  const c1Progress = interpolate(frame, [c1, c1 + c1Dur], [0, 1], clamp);
  const compressStart = interpolate(c1Progress, [0.25, 0.45], [0, 1], clamp);
  const summaryAppear = interpolate(c1Progress, [0.45, 0.60], [0, 1], clamp);
  const detailsLost = interpolate(c1Progress, [0.55, 0.72], [0, 1], clamp);

  // seg2-03: "所以当你 resume 的时候，|agent 看到的不是|第一步做了，第二步做了，第三步还没做。|它看到的是一段模糊的总结：|用户想做暗色模式，之前做了一些修改。|至于做了哪些、没做哪些、|做到哪一步了——它不知道。"
  const c2Progress = interpolate(frame, [c2, c2 + c2Dur], [0, 1], clamp);
  const vagueAppear = interpolate(c2Progress, [0.25, 0.45], [0, 1], clamp);
  const dontKnow = interpolate(c2Progress, [0.75, 0.92], [0, 1], clamp);

  const loopSteps = [
    { label: "看上下文", en: "read context", icon: "👁", entrance: step1 },
    { label: "选动作", en: "pick action", icon: "→", entrance: step2 },
    { label: "写回结果", en: "write back", icon: "↩", entrance: step3 },
  ];

  return (
    <AbsoluteFill style={{ color: THEME.colors.textPrimary }}>
      <GridBackdrop />
      <div style={{ position: "absolute", left: 60, right: 60, top: 60, bottom: 248 }}>
        {/* Cue 1: Agent loop recap — each step appears as narration names it */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[0] }}>
          <WindowFrame title="agent-loop" subtitle="each iteration">
            <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 0 }}>
              {loopSteps.map((step, i) => (
                <React.Fragment key={step.label}>
                  <div style={{
                    borderRadius: 20,
                    background: `${ACCENT}14`,
                    border: `1px solid ${ACCENT}44`,
                    padding: "28px 32px",
                    textAlign: "center",
                    minWidth: 200,
                    opacity: step.entrance,
                    transform: `scale(${interpolate(step.entrance, [0, 1], [0.88, 1])})`,
                  }}>
                    <div style={{ fontSize: 32, marginBottom: 10 }}>{step.icon}</div>
                    <div style={{ fontFamily: THEME.fonts.title, fontSize: 28, fontWeight: 800 }}>{step.label}</div>
                    <div style={{ marginTop: 6, fontSize: 14, color: THEME.colors.textSecondary, fontFamily: THEME.fonts.code }}>{step.en}</div>
                  </div>
                  {i < loopSteps.length - 1 ? (
                    <div style={{
                      width: 48, height: 4,
                      background: `linear-gradient(90deg, ${ACCENT}44, ${ACCENT}AA)`,
                      borderRadius: 999,
                      opacity: loopSteps[i + 1].entrance,
                    }} />
                  ) : null}
                </React.Fragment>
              ))}
            </div>
          </WindowFrame>
        </div>

        {/* Cue 2: Context compression — messages shrink as "自动压缩" is said */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[1] }}>
          <WindowFrame title="context-window" subtitle="messages → summary">
            <div style={{ flex: 1, display: "grid", gridTemplateColumns: "1fr 80px 1fr", gap: 16, alignItems: "stretch" }}>
              <div style={{ display: "flex", flexDirection: "column", gap: 8, overflow: "hidden" }}>
                {[
                  "user: 帮我加暗色模式",
                  "tool: edit theme.css",
                  "tool: add toggle component",
                  "agent: 已定义 CSS 变量",
                  "tool: update Header.tsx",
                  "agent: 主题开关已添加",
                  "tool: patch Button.tsx",
                  "agent: 正在改页面样式...",
                ].map((msg, i) => (
                  <div key={msg} style={{
                    borderRadius: 12,
                    background: i % 2 === 0 ? `${ACCENT}10` : "rgba(255,255,255,0.04)",
                    border: `1px solid ${i % 2 === 0 ? `${ACCENT}30` : "rgba(255,255,255,0.08)"}`,
                    padding: "10px 14px",
                    fontFamily: THEME.fonts.code,
                    fontSize: 14,
                    opacity: interpolate(compressStart, [0, 0.5], [1, 0.15], clamp),
                    transform: `scaleY(${interpolate(compressStart, [0, 1], [1, 0.12 + i * 0.02])})`,
                    transformOrigin: "top center",
                  }}>
                    {msg}
                  </div>
                ))}
              </div>

              <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8 }}>
                <div style={{ fontSize: 28, opacity: compressStart }}>⬇</div>
                <Badge label="自动压缩" color="#E3B341" style={{ fontSize: 11, opacity: compressStart }} />
              </div>

              <div style={{
                borderRadius: 18,
                background: "rgba(227,179,65,0.10)",
                border: "1px solid rgba(227,179,65,0.35)",
                padding: 20,
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                gap: 12,
                opacity: summaryAppear,
                transform: `scale(${interpolate(summaryAppear, [0, 1], [0.9, 1])})`,
              }}>
                <Badge label="summary" color="#E3B341" style={{ alignSelf: "flex-start" }} />
                <div style={{ fontSize: 20, lineHeight: 1.5, color: THEME.colors.textSecondary }}>
                  用户想做暗色模式，<br />之前做了一些修改。
                </div>
                {detailsLost > 0.3 ? (
                  <div style={{
                    marginTop: 8,
                    fontSize: 16,
                    color: "#FF7B72",
                    fontFamily: THEME.fonts.code,
                    opacity: detailsLost,
                  }}>
                    步骤细节丢了
                  </div>
                ) : null}
              </div>
            </div>
          </WindowFrame>
        </div>

        {/* Cue 3: Resume view — agent sees only vague summary */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[2] }}>
          <WindowFrame title="agent-view" subtitle="on resume">
            <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 14 }}>
              <div style={{
                borderRadius: 16,
                background: "rgba(227,179,65,0.10)",
                border: "1px dashed rgba(227,179,65,0.40)",
                padding: 18,
                opacity: vagueAppear,
              }}>
                <div style={{ fontFamily: THEME.fonts.code, fontSize: 14, color: "#E3B341", marginBottom: 8 }}>模糊的总结</div>
                <div style={{ fontSize: 22, lineHeight: 1.45, color: THEME.colors.textSecondary }}>
                  用户想做暗色模式，之前做了一些修改。
                </div>
              </div>
              <div style={{ fontFamily: THEME.fonts.code, fontSize: 13, color: THEME.colors.textSecondary, opacity: vagueAppear * 0.7 }}>
                last few messages ↓
              </div>
              {["agent: 好的，我来帮你做暗色模式", "tool: edit theme.css", "agent: 正在处理..."].map((msg, i) => (
                <div key={msg} style={{
                  borderRadius: 14,
                  background: "rgba(255,255,255,0.04)",
                  border: "1px solid rgba(255,255,255,0.08)",
                  padding: "12px 16px",
                  fontFamily: THEME.fonts.code,
                  fontSize: 15,
                  opacity: interpolate(vagueAppear, [0.2 + i * 0.1, 0.45 + i * 0.1], [0, 1], clamp),
                }}>
                  {msg}
                </div>
              ))}
              <div style={{
                marginTop: 8,
                borderRadius: 14,
                background: "rgba(255,123,114,0.10)",
                border: "1px solid rgba(255,123,114,0.35)",
                padding: 16,
                textAlign: "center",
                fontSize: 20,
                color: "#FF7B72",
                fontWeight: 700,
                opacity: dontKnow,
              }}>
                做了哪些？没做哪些？做到哪了？—— 它不知道
              </div>
            </div>
          </WindowFrame>
        </div>

        {/* Cue 4: "只能猜" — dramatic dice */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[3], display: "flex", alignItems: "center", justifyContent: "center" }}>
          <GuessDrama entrance={stagger(frame, fps, cues[3]?.relativeStartFrame ?? 0, 0)} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

