  const c1 = cues[1]?.relativeStartFrame ?? 0;
  const c1Dur = cues[1]?.durationInFrames ?? 300;

  // seg4-01: "你可能觉得，|这不就是个 todo list 吗？|也太简单了。|确实简单。|但 todo 解决的不只是 resume 的问题。|就算你不走开，|它也在防止跑偏。|因为工作循环每转一圈，|agent 都会回来看这张清单：|我做到哪了？|下一步该做什么？|哪些还没做？"
  const c0Progress = interpolate(frame, [c0, c0 + c0Dur], [0, 1], clamp);
  const simpleQ = interpolate(c0Progress, [0, 0.22], [0, 1], clamp);
  const notJustResume = interpolate(c0Progress, [0.3, 0.45], [0, 1], clamp);
  const loopCheck = interpolate(c0Progress, [0.55, 0.72], [0, 1], clamp);
  const whereAmI = interpolate(c0Progress, [0.75, 0.85], [0, 1], clamp);
  const whatsNext = interpolate(c0Progress, [0.85, 0.92], [0, 1], clamp);

  // seg4-02: "产品里还加了几条朴素的规则。|比如同一时刻|只允许一个任务处于 in progress——|光这一条，|就能压住它同时在好几个方向挖坑的冲动。|再比如，好几步都没更新过 todo，|系统会提醒它：|你是不是忘了看计划？"
  const c1Progress = interpolate(frame, [c1, c1 + c1Dur], [0, 1], clamp);
  const oneIP = interpolate(c1Progress, [0.1, 0.32], [0, 1], clamp);
  const suppressUrge = interpolate(c1Progress, [0.35, 0.55], [0, 1], clamp);
  const reminderAppear = interpolate(c1Progress, [0.65, 0.82], [0, 1], clamp);

  const glowPulse = 0.7 + Math.sin(frame / 10) * 0.15;

  return (
    <AbsoluteFill style={{ color: THEME.colors.textPrimary }}>
      <GridBackdrop />
      <div style={{ position: "absolute", left: 60, right: 60, top: 60, bottom: 248 }}>
        {/* Cue 1: Not just resume — loop + todo side by side, questions appearing */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[0], display: "grid", gridTemplateColumns: "1.15fr 0.85fr", gap: 26 }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 18 }}>
            {/* "也太简单了" question */}
            <div style={{
              ...shellPanel,
              padding: 24,
              textAlign: "center",
              opacity: simpleQ,
              transform: `scale(${interpolate(simpleQ, [0, 1], [0.92, 1])})`,
            }}>
              <div style={{ fontFamily: THEME.fonts.title, fontSize: 36, fontWeight: 800 }}>
                一个 todo list 就够了？
              </div>
            </div>

            {/* "不只是 resume" + loop diagram */}
            <div style={{ opacity: notJustResume, flex: 1 }}>
              <LoopDiagram entrance={loopCheck} />
            </div>
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <div style={{ opacity: loopCheck }}>
              <TodoBoard compact items={[
                { text: "颜色变量", status: "completed" },
                { text: "主题开关", status: "completed" },
                { text: "页面样式", status: "in_progress" },
                { text: "测试切换", status: "pending" },
              ]} />
            </div>

            {/* Questions appearing as narration asks them */}
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {[
                { text: "我做到哪了？", entrance: whereAmI },
                { text: "下一步该做什么？", entrance: whatsNext },
              ].map((q) => (
                <div key={q.text} style={{
                  borderRadius: 14,
                  background: `${ACCENT}14`,
                  border: `1px solid ${ACCENT}38`,
                  padding: "12px 18px",
                  fontFamily: THEME.fonts.code,
                  fontSize: 20,
                  color: ACCENT,
                  textAlign: "center",
                  opacity: q.entrance,
                  transform: `translateY(${interpolate(q.entrance, [0, 1], [10, 0])}px)`,
                }}>
                  {q.text}
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Cue 2: One-in-progress constraint + reminder — appearing at exact narration moment */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[1], display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ position: "relative", width: 720 }}>
            <TodoBoard items={[
              { text: "颜色变量", status: "completed" },
              { text: "主题开关", status: "completed" },
              { text: "页面样式", status: "in_progress" },
              { text: "测试切换", status: "pending" },
            ]} />

            {/* "only one in_progress" badge appears with "只允许一个任务" */}
            <div style={{
              position: "absolute",
              left: 20,
              top: 220,
              opacity: oneIP,
              transform: `translateY(${interpolate(oneIP, [0, 1], [12, 0])}px)`,
            }}>
              <Badge label="only one in_progress" color={ACCENT} style={{ fontSize: 15, padding: "8px 14px" }} />
            </div>

            {/* "压住好几个方向挖坑" — blocked arrows */}
            {suppressUrge > 0.2 ? (
              <div style={{
                position: "absolute",
                right: -50,
                top: 100,
                display: "flex",
                flexDirection: "column",
                gap: 8,
                opacity: suppressUrge,
              }}>
                {["调布局", "改字体"].map((label) => (
                  <div key={label} style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    opacity: 0.6,
                  }}>
                    <div style={{ width: 40, height: 3, background: "#FF7B7244", borderRadius: 999 }} />
                    <div style={{
                      fontSize: 16,
                      color: "#FF7B72",
                      textDecoration: "line-through",
                      fontFamily: THEME.fonts.code,
                    }}>
                      {label}
                    </div>
                    <div style={{ fontSize: 16 }}>🚫</div>
                  </div>
                ))}
              </div>
            ) : null}

            {/* Reminder bubble — appears with "系统会提醒它" */}
            <div style={{
              position: "absolute",
              right: -30,
              top: 180,
              padding: "14px 20px",
              borderRadius: 18,
              background: "rgba(227,179,65,0.14)",
              border: "1px solid rgba(227,179,65,0.45)",
              fontFamily: THEME.fonts.code,
              fontSize: 18,
              color: "#E3B341",
              fontWeight: 700,
              maxWidth: 320,
              opacity: reminderAppear,
              transform: `translateY(${interpolate(reminderAppear, [0, 1], [12, 0])}px)`,
            }}>
              ⚡ 你是不是忘了看计划？
            </div>
          </div>
        </div>

        {/* Cue 3: Closing — glowing checklist icon + "不会被淹没的清单" */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[2], display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 32 }}>
          <div style={{
            width: 120,
            height: 120,
            borderRadius: 28,
            background: `${ACCENT}${Math.round(glowPulse * 30).toString(16).padStart(2, "0")}`,
            border: `2px solid ${ACCENT}`,
            boxShadow: `0 0 ${40 * glowPulse}px ${ACCENT}55, inset 0 0 30px ${ACCENT}22`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 52,
            transform: `scale(${interpolate(stagger(frame, fps, cues[2]?.relativeStartFrame ?? 0, 0), [0, 1], [0.8, 1])})`,
          }}>
            ☑
          </div>
          <div style={{
            fontFamily: THEME.fonts.title,
            fontSize: 48,
            fontWeight: 800,
            textAlign: "center",
            lineHeight: 1.3,
            opacity: stagger(frame, fps, (cues[2]?.relativeStartFrame ?? 0) + 20, 0),
          }}>
            不会被淹没的清单
          </div>
          <div style={{
            display: "flex",
            gap: 32,
            opacity: stagger(frame, fps, (cues[2]?.relativeStartFrame ?? 0) + 40, 0),
          }}>
            {[
              { label: "防跑偏", color: ACCENT },
              { label: "断点续传", color: "#3FB950" },
            ].map((v) => (
              <Badge key={v.label} label={v.label} color={v.color} style={{ fontSize: 20, padding: "10px 18px" }} />
            ))}
          </div>
        </div>

        {/* Cue 4: Next episode preview — Hooks */}
        <div style={{ position: "absolute", inset: 0, opacity: cueOpacities[3], display: "flex", alignItems: "center", justifyContent: "center" }}>
          <HooksPreviewCard entrance={stagger(frame, fps, cues[3]?.relativeStartFrame ?? 0, 0)} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

