}

import timingJson from "./s01e07-timing.json";

export type AudioVariant = "cn" | "en";
export type SegmentId = "seg1" | "seg2" | "seg3" | "seg4" | "seg5";

export interface CueTiming {
  id: string;
  summary: string;
  cn: string;
  en: string;
  highlights: {
    cn: string[];
    en: string[];
  };
  relativeStartFrame: number;
  relativeEndFrameExclusive: number;
  absoluteStartFrame: number;
  absoluteEndFrameExclusive: number;
  durationInFrames: number;
  cnDurationSeconds: number;
  enDurationSeconds: number;
  audio: Record<AudioVariant, string>;
}

export interface SegmentTiming {
  id: SegmentId;
  title: string;
  narrativeRoute: string;
  visualPhases: string[];
  targetDurationSeconds: number;
  relativeStartFrame: number;
  relativeEndFrameExclusive: number;
  absoluteStartFrame: number;
  absoluteEndFrameExclusive: number;
  durationInFrames: number;
  cues: CueTiming[];
}

export interface EpisodeTiming {
  seriesSlug: string;
  episodeSlug: string;
  compositionId: string;
  previewCnId: string;
  previewEnId: string;
  seriesName: string;
  episodeCode: string;
  episodeTitleCn: string;
  episodeTitleEn: string;
  nextEpisodeCode: string;
  nextEpisodeTitle: string;
  fps: number;
  width: number;
  height: number;
  introFrames: number;
  outroFrames: number;
  cueGapFrames: number;
  subtitleSafetyHeight: number;
  contentDurationInFrames: number;
  fullDurationInFrames: number;
}

interface TimingData {
  episode: EpisodeTiming;
  warnings: string[];
  segments: SegmentTiming[];
}

const timingData = timingJson as TimingData;

export const S01E07_EPISODE = timingData.episode;
export const S01E07_WARNINGS = timingData.warnings;
export const S01E07_SEGMENTS = timingData.segments;
export const S01E07_FULL_DURATION = timingData.episode.fullDurationInFrames;

export const getSegmentTiming = (segmentId: SegmentId): SegmentTiming => {
  const match = S01E07_SEGMENTS.find((segment) => segment.id === segmentId);

  if (!match) {
    throw new Error(`Unknown segment: ${segmentId}`);
  }

  return match;
};

