const staggerSpring = (startFrame: number, index: number, gap = 10) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  return spring({
    frame: Math.max(0, frame - startFrame - index * gap),
    fps,
    config: { damping: 16, stiffness: 92, mass: 0.9 },
  });
};

