```typescript
const staggerVal = (frame: number, fps: number, startFrame: number, index: number, gap = 10) =>
  spring({
    frame: Math.max(0, frame - startFrame - index * gap),
    fps,
    config: { damping: 16, stiffness: 92, mass: 0.9 },
  });
```
3. Use `usePhaseFade` for cross-dissolve between cue phases
4. Use `PhaseLayer` for absolute positioning with opacity-based pointer events

## Code Constants Needed
Three matmul versions:
```typescript
const PYTHON_MATMUL = `def matmul(a, b, c, n):
    for i in range(n):
        for j in range(n):
            for k in range(n):
                c[i][j] += a[i][k] * b[k][j]`;

const CPP_MATMUL = `void matmul(double* a, double* b,
             double* c, int n) {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            for (int k = 0; k < n; k++)
                c[i*n+j] += a[i*n+k] * b[k*n+j];
}`;

const RUST_MATMUL = `fn matmul(a: &[f64], b: &[f64],
         c: &mut [f64], n: usize) {
    for i in 0..n {
        for j in 0..n {
            for k in 0..n {
                c[i*n+j] += a[i*n+k] * b[k*n+j];
            }
        }
    }
}`;
```

